inline void to_string(const CRLReason& value, std::ostream& out, int indent) {
    (void)indent;
    switch (value) {
    case CRLReason::unspecified:
        out << "unspecified";
        break;
    case CRLReason::keyCompromise:
        out << "keyCompromise";
        break;
    case CRLReason::cACompromise:
        out << "cACompromise";
        break;
    case CRLReason::affiliationChanged:
        out << "affiliationChanged";
        break;
    case CRLReason::superseded:
        out << "superseded";
        break;
    case CRLReason::cessationOfOperation:
        out << "cessationOfOperation";
        break;
    case CRLReason::certificateHold:
        out << "certificateHold";
        break;
    case CRLReason::removeFromCRL:
        out << "removeFromCRL";
        break;
    case CRLReason::privilegeWithdrawn:
        out << "privilegeWithdrawn";
        break;
    case CRLReason::aACompromise:
        out << "aACompromise";
        break;
    default:
        out << static_cast<std::int32_t>(value);
        break;
    }
}

